begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.au(n int) returns uuid language sql immutable as $$
select ('50000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid;
$$;
create temporary table ar_fixture(name text primary key,id uuid);
create function pg_temp.aid(name text) returns uuid language sql stable as $$
select id from ar_fixture where ar_fixture.name=$1;
$$;
create function pg_temp.err(command text) returns text language plpgsql as $$
begin execute command; return '00000'; exception when others then return sqlstate; end;
$$;
do $$ begin execute format('grant usage on schema %I to anon,authenticated,service_role',pg_my_temp_schema()::regnamespace::text); end $$;
grant all on ar_fixture to service_role;
grant execute on function pg_temp.au(int),pg_temp.aid(text),pg_temp.err(text) to anon,authenticated,service_role;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.au(n),'ar-'||n||'@example.invalid',jsonb_build_object('username','ar_'||n) from generate_series(1,4) n;
select ok(not has_function_privilege('anon','public.authorize_ar_mascot(uuid,text,text)','EXECUTE'),'anon cannot authorize');
select ok(not has_function_privilege('authenticated','public.authorize_ar_mascot(uuid,text,text)','EXECUTE'),'authenticated cannot authorize');
select ok(not has_function_privilege('authenticated','public.grant_verified_ar_mascot(uuid,uuid,text)','EXECUTE'),'authenticated cannot grant');
set local role service_role;
select throws_ok($q$select public.authorize_ar_mascot(null,'charros-jal','x')$q$,'P0001','Invalid AR authorization.','NULL identity');
select throws_ok($q$select public.authorize_ar_mascot(pg_temp.au(1),'invalid','x')$q$,'P0001','AR team not available.','unknown team');
select throws_ok($q$select public.authorize_ar_mascot(pg_temp.au(1),'charros-jal',' ')$q$,'P0001','Invalid AR authorization.','empty reference');
insert into ar_fixture values('one',public.authorize_ar_mascot(pg_temp.au(1),'charros-jal','proof-one'));
select is(public.authorize_ar_mascot(pg_temp.au(1),'charros-jal','proof-one'),pg_temp.aid('one'),'authorization retry');
select throws_ok($q$select public.authorize_ar_mascot(pg_temp.au(2),'charros-jal','proof-one')$q$,'P0001','AR verification belongs to another operation.','reference cannot change owner');
select throws_ok($q$select public.authorize_ar_mascot(pg_temp.au(1),'dorados-chi','proof-one')$q$,'P0001','AR verification belongs to another operation.','reference cannot change team');
select throws_ok($q$select public.authorize_ar_mascot(pg_temp.au(1),'charros-jal','another-proof')$q$,'P0001','AR authorization already exists.','one authorization per resource');
insert into public.activity_attempts(id,user_id,activity_type,metadata) values(pg_temp.au(20),pg_temp.au(1),'ar','{"scanned":true,"ar_verified_at":"2026-10-25","card_id":7}');
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.au(20),'fake')$q$,'P0001','Trusted AR verification required.','metadata cannot authorize');
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(2),pg_temp.aid('one'),'foreign')$q$,'P0001','AR attempt not found.','foreign owner rejected');
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.au(99),'missing')$q$,'P0001','AR attempt not found.','missing attempt');
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('one'),' ')$q$,'P0001','Invalid AR grant.','empty request key');
select is(public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('one'),'shared')->>'already_processed','false','first trusted grant');
select is(public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('one'),'shared')->>'already_processed','true','same request retry');
select is((select count(*) from public.user_cards where user_id=pg_temp.au(1)),1::bigint,'one inventory row');
select is((select source from public.user_cards where user_id=pg_temp.au(1)),'ar','AR source recorded');
select is((select c.slug from public.user_cards u join public.cards c on c.id=u.card_id where u.user_id=pg_temp.au(1)),'straiky','server resolves exact mascot');
select is((select points_balance from public.profiles where id=pg_temp.au(1)),0,'no points charged');
select is((select status from public.activity_attempts where id=pg_temp.aid('one')),'completed','attempt completed');
select is((select count(*) from public.reward_events where attempt_id=pg_temp.aid('one')),1::bigint,'one ledger event');
select is((select points_delta from public.reward_events where attempt_id=pg_temp.aid('one')),0,'zero points ledger');
select is(pg_temp.err($q$insert into public.reward_events(user_id,attempt_id,event_type,points_delta,card_id,idempotency_key,idempotency_version) values(pg_temp.au(1),pg_temp.aid('one'),'ar_mascot_unlock',0,(select id from public.cards where slug='perro-sultan'),'wrong-team',2)$q$),'P0001','wrong mascot/team association denied');
select is(pg_temp.err($q$insert into public.reward_events(user_id,attempt_id,event_type,points_delta,card_id,idempotency_key,idempotency_version) values(pg_temp.au(1),pg_temp.aid('one'),'ar_mascot_unlock',100,(select id from public.cards where slug='straiky'),'wrong-points',2)$q$),'P0001','AR event cannot grant points');
select is(pg_temp.err($q$insert into public.reward_events(user_id,attempt_id,event_type,points_delta,card_id,idempotency_key,idempotency_version) values(pg_temp.au(2),pg_temp.aid('one'),'ar_mascot_unlock',0,(select id from public.cards where slug='straiky'),'wrong-owner',2)$q$),'P0001','ledger owner must match verified attempt');
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('one'),'different')$q$,'P0001','AR attempt is not active.','new key cannot grant same attempt again');
insert into ar_fixture values('other-team',public.authorize_ar_mascot(pg_temp.au(1),'sultanes-mty','proof-other-team'));
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('other-team'),'shared')$q$,'P0001','AR operation state is inconsistent.','same key cannot grant different team');
insert into ar_fixture values('other-user',public.authorize_ar_mascot(pg_temp.au(2),'charros-jal','proof-other-user'));
select is(public.grant_verified_ar_mascot(pg_temp.au(2),pg_temp.aid('other-user'),'shared')->>'already_processed','false','same raw key isolated by user');
insert into public.user_cards(user_id,card_id,source) select pg_temp.au(3),id,'legacy' from public.cards where slug='pancho-pistolas';
insert into ar_fixture values('owned',public.authorize_ar_mascot(pg_temp.au(3),'dorados-chi','proof-owned'));
select is(public.grant_verified_ar_mascot(pg_temp.au(3),pg_temp.aid('owned'),'owned')->>'already_owned','true','already owned explicitly reported');
select is((select source from public.user_cards where user_id=pg_temp.au(3)),'legacy','existing ownership source preserved');
select is((select count(*) from public.user_cards where user_id=pg_temp.au(3)),1::bigint,'already owned not duplicated');
select is(pg_temp.err($q$select public.complete_activity_attempt(pg_temp.au(1),pg_temp.aid('other-team'),'ar_points','bad',null,100)$q$),'P0001','generic RPC cannot credit a verified AR attempt');
select is((select points_balance from public.profiles where id=pg_temp.au(1)),0,'failed generic grant rolls balance back');
select is((select status from public.activity_attempts where id=pg_temp.aid('other-team')),'started','failed generic grant rolls attempt back');
select is(pg_temp.err($q$insert into public.reward_events(user_id,attempt_id,event_type,points_delta,card_id,idempotency_key) values(pg_temp.au(1),pg_temp.au(20),'ar_mascot_unlock',0,(select id from public.cards where slug='straiky'),'unverified')$q$),'P0001','legacy event version cannot bypass verification');
reset role;
-- A final ledger failure must undo both inventory insertion and completion.
create function pg_temp.fail_ar_event() returns trigger language plpgsql as $$ begin raise exception 'Forced local AR ledger failure.'; end; $$;
create trigger zz_fail_ar_event before insert on public.reward_events for each row execute function pg_temp.fail_ar_event();
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('other-team'),'rollback')$q$,'P0001','Forced local AR ledger failure.','ledger failure propagated');
select is((select count(*) from public.user_cards where user_id=pg_temp.au(1)),1::bigint,'failed grant leaves no second mascot');
select is((select status from public.activity_attempts where id=pg_temp.aid('other-team')),'started','failed grant restores attempt');
drop trigger zz_fail_ar_event on public.reward_events;
update public.cards set is_active=false where slug='perro-sultan';
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('other-team'),'inactive')$q$,'P0001','AR mascot catalog is invalid.','inactive mascot denied');
update public.cards set is_active=true where slug='perro-sultan';
update public.teams set is_active=false where slug='sultanes-mty';
select throws_ok($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.aid('other-team'),'inactive-team')$q$,'P0001','AR team not available.','inactive team denied');
update public.teams set is_active=true where slug='sultanes-mty';
select is(pg_temp.err($q$update public.activity_attempts set ar_verified_at=null where id=pg_temp.aid('other-team')$q$),'23514','NULL cannot weaken authorization shape');
set local role anon;
select is(pg_temp.err($q$select public.authorize_ar_mascot(pg_temp.au(1),'sultanes-mty','browser')$q$),'42501','anon authorization actually denied');
set local role authenticated;
select is(pg_temp.err($q$select public.grant_verified_ar_mascot(pg_temp.au(1),pg_temp.au(99),'browser')$q$),'42501','authenticated grant actually denied');
select is(pg_temp.err($q$insert into public.user_cards(user_id,card_id,source) values(pg_temp.au(1),1,'ar')$q$),'42501','browser cannot insert ownership');
reset role;
select * from finish();
rollback;
